select 
from review_notify_channel c
where c.channel_id = #{channelId}

select channel_id, channel_name, channel_type, webhook_url_ciphertext, secret_ciphertext, status
from review_notify_channel
where channel_id = #{channelId}

select 
from review_notify_channel c
where 1 = 1

    and c.channel_name like concat('%', #{channelName}, '%')


    and c.channel_type = #{channelType}


    and c.status = #{status}


    and c.last_check_status = #{lastCheckStatus}

order by c.channel_id desc

select channel_id, channel_name, channel_type
from review_notify_channel
where channel_type = #{channelType}
  and channel_name = #{channelName}

  and channel_id != #{excludeChannelId}

limit 1

mapper.update:
update review_notify_channel
channel_name = #{channelName}, channel_type = #{channelType}, webhook_url_ciphertext = #{webhookUrlCiphertext}, secret_ciphertext = #{secretCiphertext}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where channel_id = #{channelId}

update review_notify_channel
set last_check_status = 'UNTESTED', last_check_message = null, last_check_time = null
where channel_id = #{channelId}
